const query = items[0].json.query || {};
const mode = query['hub.mode'];
const token = query['hub.verify_token'];
const challenge = query['hub.challenge'];
const expectedToken = process.env.WHATSAPP_VERIFY_TOKEN || 'tabibi_webhook_verify_secret';
if (mode === 'subscribe' && token === expectedToken) {
  return [{ json: { status: 200, response: challenge || 'OK' } }];
}
return [{ json: { status: 403, response: 'Forbidden' } }];

const body = items[0].json.body || {};
const entry = body.entry?.[0];
const change = entry?.changes?.[0]?.value;
const message = change?.messages?.[0];
const metadata = change?.metadata;
if (!message || !message.from) {
  return [];
}
const patientPhone = message.from;
const messageText = message.text?.body || message.caption || 'سلام عليكم';
const messageId = message.id;
const timestamp = message.timestamp;
const displayPhoneNumber = metadata?.display_phone_number;
const whatsappPhoneNumberId = metadata?.phone_number_id;
return [{ json: { patientPhone, messageText, messageId, timestamp, displayPhoneNumber, whatsappPhoneNumberId } }];

const staticData = $getWorkflowStaticData('global');
staticData.processedIds = staticData.processedIds || [];
const item = items[0].json;
const msgId = item.messageId;
if (staticData.processedIds.includes(msgId)) {
  return [];
}
staticData.processedIds.push(msgId);
if (staticData.processedIds.length > 500) {
  staticData.processedIds.shift();
}
return items;

const doctors = items[0].json.doctors || [];
const webhookData = $node['4. Idempotency & Deduplication Filter'].json;
let doctor = doctors.find(d => d.whatsappNumber === webhookData.patientPhone || d.whatsappNumber === webhookData.displayPhoneNumber);
if (!doctor && doctors.length > 0) {
  doctor = doctors[0];
}
return [{ json: { doctorId: doctor ? doctor.id : '', doctorName: doctor ? doctor.name : 'د. أحمد محمد', patientPhone: webhookData.patientPhone, messageText: webhookData.messageText, messageId: webhookData.messageId, whatsappPhoneNumberId: webhookData.whatsappPhoneNumberId } }];

const res = items[0].json;
const prev = $node['Select Active Doctor'].json;
const output = res.output || {};
const replyText = output.replyText || 'أهلاً بحضرتك! سيقوم مساعد الاستقبال بالرد عليك فوراً.';
return [{ json: { replyText, handledBy: output.handledBy || 'RULE_TEMPLATE', intent: output.intent || 'UNKNOWN', patientPhone: prev.patientPhone, doctorId: prev.doctorId, doctorName: prev.doctorName, whatsappPhoneNumberId: prev.whatsappPhoneNumberId } }];

const item = items[0].json;
console.log(`[LOCAL DEV MODE] Reply sent to ${item.patientPhone} for ${item.doctorName}:`);
console.log(item.replyText);
return items;
